"""LEAVES_I_PN scripts bundle (Grok, green_regular_character lane, 2026-11-24).
Bundled into one file only because the commit tool limits the number of file arguments per commit.
Run `python3 LEAVES_I_PN_scripts_bundle.py [outdir]` to write the four files below byte-for-byte:
  LEAVES_I_PN_UpstreamIdentityCheck.lean  rfl identity + axioms in the pinned upstream env (run with LEAVES_I_PN_run_pinned_env.sh)
  LEAVES_I_PN_leaf_exact_checks.py        exact finite checks (pure integers)
  LEAVES_I_PN_mk_companion.py             generator of LEAVES_I_PN_GreenLeafCompanion.lean from the raw pin fetch
  LEAVES_I_PN_run_pinned_env.sh           exact lean invocation (LEAN_PATH, upstream leanOptions)
"""
import os, sys
FILES = {
 "LEAVES_I_PN_UpstreamIdentityCheck.lean": "import Development.AbelianVarietyTheory.Proofs.InertiaEigenvalues.MonicIrreducibleInjectRegularCharacterOrbitsStatement\nimport Development.AbelianVarietyTheory.Proofs.InertiaEigenvalues.NcardMonicNatDegreeCoeffZeroNeZeroStatement\n/-! Grok green_regular_character LEAF RUN — identity check against the published pinned environment\n(upstream oleans, frozen mirror). Checks (1) the companion's textual copies of IsPrimeLab / IsRegularChar are\ndefinitionally equal (by `rfl`, kernel-checked) to the upstream constants; (2) the companion's statement texts\nare exactly the upstream theorem types; (3) axioms of the upstream constants. -/\nopen Polynomial\nopen scoped Classical\nnamespace GrokLeafCopy\nvariable {g : ℕ} [Fact g.Prime]\ndef IsPrimeLab (d : ℕ) (P : (ZMod g)[X]) : Prop := P.Monic ∧ Irreducible P ∧ P.coeff 0 ≠ 0 ∧ P.natDegree = d\nend GrokLeafCopy\nnamespace GrokLeafCopy\ndef IsRegularChar (g d : ℕ) {K : Type} [Field K] (θ : Kˣ →* ℂˣ) : Prop :=\n  ∀ i j, i < d → j < d → θ ^ g ^ i = θ ^ g ^ j → i = j\nend GrokLeafCopy\n\ntheorem grok_isPrimeLab_eq : @GrokLeafCopy.IsPrimeLab = @GlobalTheory.GLq.IsPrimeLab := rfl\ntheorem grok_isRegularChar_eq : @GrokLeafCopy.IsRegularChar = @GlobalTheory.Published.IsRegularChar := rfl\n\nopen GlobalTheory.GLq GlobalTheory.Published in\nexample : ∀ (g : ℕ) [Fact g.Prime] (n : ℕ), 0 < n → Set.ncard {f : (ZMod g)[X] | f.Monic ∧ f.natDegree = n ∧ f.coeff 0 ≠ 0} = g ^ n - g ^ (n - 1) ∧ Set.Finite {f : (ZMod g)[X] | f.Monic ∧ f.natDegree = n ∧ f.coeff 0 ≠ 0} :=\n  @GlobalTheory.T.ncard_monic_natDegree_coeff_zero_ne_zero\nopen GlobalTheory.GLq GlobalTheory.Published in\nexample : ∀ (g : ℕ) [Fact g.Prime] (d : ℕ), 0 < d → ∀ (K : Type) [Field K] [Algebra (ZMod g) K], Module.finrank (ZMod g) K = d → ∃ c : (ZMod g)[X] → (Kˣ →* ℂˣ), (∀ P, IsPrimeLab d P → IsRegularChar g d (c P)) ∧ ∀ P P', IsPrimeLab d P → IsPrimeLab d P' → (∃ i < d, c P' = c P ^ g ^ i) → P = P' :=\n  @GlobalTheory.T.monicIrreducible_inject_regularCharacterOrbits\n-- the upstream wrapper names are definitionally the proof-file theorems' statements\nexample : type_of% @GlobalTheory.T.ncard_monic_natDegree_coeff_zero_ne_zero = type_of% @GlobalTheory.GrPolys.card_monic_coeff_zero_ne_zero := rfl\nexample : type_of% @GlobalTheory.T.monicIrreducible_inject_regularCharacterOrbits = type_of% @GlobalTheory.PrimeLabOrbit.primeLab_to_regularChar := rfl\n\n#print axioms GlobalTheory.GrPolys.card_monic_coeff_zero_ne_zero\n#print axioms GlobalTheory.PrimeLabOrbit.primeLab_to_regularChar\n#print axioms GlobalTheory.T.ncard_monic_natDegree_coeff_zero_ne_zero\n#print axioms GlobalTheory.T.monicIrreducible_inject_regularCharacterOrbits\n#print axioms grok_isPrimeLab_eq\n#print axioms grok_isRegularChar_eq\n",
 "LEAVES_I_PN_leaf_exact_checks.py": "\"\"\"Exact finite checks for the two Theorem A leaves (Grok, green_regular_character LEAF RUN).\nPure-integer arithmetic over F_g; no floating point, no random input. These are instances, not proofs.\nPn: #{monic f in F_g[X], deg f = n, f(0) != 0} = g^n - g^(n-1)  (and #{monic deg n} = g^n, #{... f(0)=0} = g^(n-1)).\nI : in K = F_{g^d} (built as F_g[x]/(Q), Q a fixed monic irreducible of degree d), for every IsPrimeLab-d P:\n    (a) P has a root u in K^x;  (b) u, u^g, ..., u^(g^(d-1)) are pairwise distinct (regularity, upstream orbit_regular);\n    (c) with K^x = <zeta>, log: K^x -> Z/(q-1), the character e(u): zeta^k -> exp(2 pi i k log(u)/(q-1)) is encoded\n        exactly by log(u) mod q-1; e(u)^(g^i) = e(u^(g^i)) and e(u)=e(v) <=> u=v (e is the MulEquiv of the proof);\n    (d) if c(P') = c(P)^(g^i) for some i<d then P = P' (injectivity on prime labels modulo Frobenius orbits);\n    (e) number of regular characters of K^x  ==  d * #{IsPrimeLab-d P}.\n\"\"\"\nimport itertools\ndef trim(p):\n    while p and p[-1] == 0: p.pop()\n    return p\ndef pmod(a, m, g):\n    a = trim(a[:]); m = trim(m[:]); inv = pow(m[-1], g - 2, g)\n    while len(a) >= len(m):\n        c = a[-1] * inv % g; s = len(a) - len(m)\n        for i, x in enumerate(m): a[s + i] = (a[s + i] - c * x) % g\n        trim(a)\n    return a\ndef pmul(a, b, g):\n    r = [0] * (len(a) + len(b) - 1) if a and b else []\n    for i, x in enumerate(a):\n        for j, y in enumerate(b): r[i + j] = (r[i + j] + x * y) % g\n    return trim(r)\ndef monics(g, n):\n    for cs in itertools.product(range(g), repeat=n): yield list(cs) + [1]\ndef irreducible(f, g):\n    n = len(f) - 1\n    for k in range(1, n // 2 + 1):\n        for h in monics(g, k):\n            if not pmod(f, h, g): return False\n    return True\ndef is_prime_lab(f, g, d): return len(f) - 1 == d and f[0] != 0 and irreducible(f, g)\ndef check_Pn(g, n):\n    tot = nz = z = 0\n    for f in monics(g, n):\n        tot += 1\n        if f[0] != 0: nz += 1\n        else: z += 1\n    return tot == g**n and z == g**(n-1) and nz == g**n - g**(n-1), (tot, z, nz)\ndef check_I(g, d):\n    q = g**d\n    Q = next(f for f in monics(g, d) if is_prime_lab(f, g, d) or (d == 1 and f == [0, 1]))\n    if d == 1: Q = [0, 1]\n    mul = lambda a, b: tuple((pmod(pmul(list(a), list(b), g), Q, g) + [0] * d)[:d])\n    one = tuple([1] + [0] * (d - 1))\n    elems = [e for e in itertools.product(range(g), repeat=d) if any(e)]\n    def pw(a, k):\n        r, b = one, a\n        while k:\n            if k & 1: r = mul(r, b)\n            b = mul(b, b); k >>= 1\n        return r\n    gen = next(a for a in elems if all(pw(a, (q - 1) // p) != one for p in {p for p in range(2, q) if (q - 1) % p == 0 and all(p % r for r in range(2, p))}))\n    log, x = {}, one\n    for k in range(q - 1): log[x] = k; x = mul(x, gen)\n    assert len(log) == q - 1\n    def aeval(u, P):\n        r = tuple([0] * d)\n        for c in reversed(P):\n            r = mul(r, u); r = tuple((r[0] + c) % g if i == 0 else r[i] for i in range(d))\n        return r\n    zero = tuple([0] * d)\n    labs = [P for P in monics(g, d) if is_prime_lab(P, g, d)]\n    c = {}\n    for P in labs:\n        roots = [u for u in elems if aeval(u, P) == zero]\n        if not roots: return False, \"no unit root\"                      # (a)\n        u = roots[0]\n        orb = [pw(u, g**i) for i in range(d)]\n        if len(set(orb)) != d: return False, \"not regular\"              # (b)\n        c[tuple(P)] = log[u]\n    m = q - 1\n    # (c) character encoding: e(u)^(g^i) <-> g^i*log u mod m equals log(u^(g^i))\n    for u in elems:\n        for i in range(d):\n            if (g**i * log[u]) % m != log[pw(u, g**i)]: return False, \"frobenius-pow mismatch\"\n    # (d)\n    for P, P2 in itertools.product(labs, repeat=2):\n        if any(c[tuple(P2)] == (c[tuple(P)] * g**i) % m for i in range(d)) and P != P2: return False, \"not injective\"\n    # (e) regular characters of Z/m: k with k*g^i distinct mod m for i<d\n    nreg = sum(1 for k in range(m) if len({(k * g**i) % m for i in range(d)}) == d)\n    if nreg != d * len(labs): return False, (\"count\", nreg, len(labs))\n    return True, (q, len(labs), nreg)\nif __name__ == \"__main__\":\n    bad = 0\n    print(\"== Pn: #monic deg n = g^n; #(f(0)=0) = g^(n-1); #(f(0)!=0) = g^n - g^(n-1)\")\n    for g, n in [(2,1),(2,2),(2,3),(2,4),(2,5),(3,1),(3,2),(3,3),(3,4),(5,1),(5,2),(5,3),(7,2)]:\n        ok, data = check_Pn(g, n); bad += not ok\n        print(f\"g={g} n={n}: (total, zero-const, nonzero-const) = {data} {'ok' if ok else 'MISMATCH'}\")\n    print(\"== I: prime labels of degree d -> regular characters of F_{g^d}^x, injective modulo Frobenius orbits\")\n    for g, d in [(2,1),(2,2),(2,3),(2,4),(2,5),(3,1),(3,2),(3,3),(5,1),(5,2),(7,2)]:\n        ok, data = check_I(g, d); bad += not ok\n        print(f\"g={g} d={d}: (q, #IsPrimeLab, #regular chars = d*#labels) = {data} {'ok' if ok else 'MISMATCH'}\")\n    print(f\"mismatches = {bad}\")\n",
 "LEAVES_I_PN_mk_companion.py": "\"\"\"Generator for the Grok green_regular_character leaf companion (Theorem A leaves I and Pn).\nTextual operations only. Reads upstream files fetched by raw URL at pin\n40e56bab026552e089d7afcfeff08d2defb9c005 (from /workspace/lean_rh_routine/up) and writes\nGreenLeafCompanion.lean: verbatim definitions + verbatim proof files (imports replaced by `import Mathlib`).\"\"\"\nimport sys, hashlib\nU = sys.argv[1] if len(sys.argv) > 1 else \"/workspace/lean_rh_routine/up/\"\nIE = \"src/Development/AbelianVarietyTheory/Proofs/InertiaEigenvalues/\"\nLD = \"src/Development/AbelianVarietyTheory/Definitions/NonGaloisDescent/LabelDatum.lean\"\nGR = \"src/Development/AbelianVarietyTheory/PublishedTheorems/GaloisCohomology\\u2082/GreenRegularCharacters.lean\"\ndef rd(p): return open(U + p, encoding=\"utf-8\").read()\ndef strip_imports(t):\n    return \"\\n\".join(l for l in t.split(\"\\n\") if not l.startswith(\"import \")).strip(\"\\n\") + \"\\n\"\ndef line_of(t, key):\n    return [l for l in t.split(\"\\n\") if l.startswith(key)]\nld = rd(LD); gr = rd(GR)\nisprime = line_of(ld, \"def IsPrimeLab \")\nassert len(isprime) == 1\na = gr.index(\"def IsRegularChar \"); b = gr.index(\"\\n\\n\", a)\nisreg = gr[a:b]\nout = []\nout.append(\"/-\\nGrok green_regular_character LEAF RUN: verbatim companion for Theorem A leaves I and Pn.\\n\"\n           \"Upstream leanprover-community/riemann-hypothesis @ 40e56bab026552e089d7afcfeff08d2defb9c005.\\n\"\n           \"Generated by mk_companion.py (textual slicing; definitional identity with upstream constants is\\n\"\n           \"checked only by text equality of the definition lines, not by the Lean kernel against upstream .olean).\\n-/\\n\")\nout.append(\"import Mathlib\\n\\n-- [LabelDatum.lean:6-9,30,91] verbatim header + IsPrimeLab\\nnoncomputable section\\nnamespace GlobalTheory.GLq\\nopen Polynomial\\nopen scoped Classical\\nvariable {g : ℕ} [Fact g.Prime]\\n\" + isprime[0] + \"\\nend GlobalTheory.GLq\\nend\\n\")\nout.append(\"\\n-- [GreenRegularCharacters.lean:4-10] verbatim header + IsRegularChar\\nnoncomputable section\\nopen Polynomial GlobalTheory.GLq\\nnamespace GlobalTheory.Published\\n\" + isreg + \"\\nend GlobalTheory.Published\\nend\\n\")\n# the upstream opens a namespace that would otherwise not exist without ArithmeticCylinders\nout.append(\"\\nnamespace Formalism.MainNotions.ArithmeticCylinders\\nend Formalism.MainNotions.ArithmeticCylinders\\n\")\nfor f in [\"NcardMonicNatDegreeCoeffZeroNeZero.lean\", \"MonicIrreducibleInjectRegularCharacterOrbits.lean\",\n          \"NcardMonicNatDegreeCoeffZeroNeZeroStatement.lean\", \"MonicIrreducibleInjectRegularCharacterOrbitsStatement.lean\"]:\n    t = rd(IE + f)\n    out.append(\"\\n-- ===== verbatim body of \" + IE + f + \" (git blob sha1 computed below in VALIDATION log) =====\\nsection\\n\" + strip_imports(t) + \"end\\n\")\nout.append(\"\"\"\n-- ===== axiom audit =====\n#print axioms GlobalTheory.GrPolys.card_monic_coeff_zero_ne_zero\n#print axioms GlobalTheory.PrimeLabOrbit.primeLab_to_regularChar\n#print axioms GlobalTheory.T.ncard_monic_natDegree_coeff_zero_ne_zero\n#print axioms GlobalTheory.T.monicIrreducible_inject_regularCharacterOrbits\n#check @GlobalTheory.GLq.IsPrimeLab\n#check @GlobalTheory.Published.IsRegularChar\n\"\"\")\nopen(\"GreenLeafCompanion.lean\", \"w\", encoding=\"utf-8\").write(\"\".join(out))\nprint(\"written\")\n",
 "LEAVES_I_PN_run_pinned_env.sh": "#!/usr/bin/env bash\n# usage: run_pinned_env.sh FILE.lean  — elaborate FILE against the published pinned upstream environment:\n# Mathlib/deps at the upstream lake-manifest pins (/workspace/rh_orig/.lake/packages) + the 175,187 upstream\n# oleans of the frozen mirror (symlink farm /workspace/rh_full_build, built by the lean_validation lane), with\n# the upstream lakefile [leanOptions]. Read-only use of both; no .olean is written (no -o).\nR=/workspace/rh_orig/.lake/packages\nexport LEAN_PATH=$R/Cli/.lake/build/lib/lean:$R/batteries/.lake/build/lib/lean:$R/Qq/.lake/build/lib/lean:$R/aesop/.lake/build/lib/lean:$R/proofwidgets/.lake/build/lib/lean:$R/importGraph/.lake/build/lib/lean:$R/LeanSearchClient/.lake/build/lib/lean:$R/plausible/.lake/build/lib/lean:$R/mathlib/.lake/build/lib/lean:/workspace/rh_full_build/lib/lean:$HOME/.elan/toolchains/leanprover--lean4---v4.33.1/lib/lean\nexport LEAN_ABORT_ON_PANIC=1 OMP_NUM_THREADS=1\nstart=$(date +%s)\necho \"+ lean [upstream leanOptions] $1  ($(date -Is))\"\nnice -n 10 $HOME/.elan/toolchains/leanprover--lean4---v4.33.1/bin/lean -DautoImplicit=false -DrelaxedAutoImplicit=false -DmaxSynthPendingDepth=3 -Dpp.unicode.fun=true -DmaxHeartbeats=4000000 --tstack=400000 \"$1\"\necho \"EXIT=$? elapsed=$(( $(date +%s)-start ))s\"\n"
}
if __name__ == "__main__":
    out = sys.argv[1] if len(sys.argv) > 1 else "."
    os.makedirs(out, exist_ok=True)
    for n, t in FILES.items():
        with open(os.path.join(out, n), "w", encoding="utf-8") as f: f.write(t)
        if n.endswith(".sh"): os.chmod(os.path.join(out, n), 0o755)
        print("wrote", n)
